import{_ as s,l as i,o as e,c as n,v as t,p as l,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"GeoDNS","description":"","frontmatter":{"title":"GeoDNS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/geodns.md","filePath":"cs/geodns.md","lastUpdated":1789023840000}'),h={name:"cs/geodns.md"};function S(T,a,_,E,P,D){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="geodns" tabindex="-1">GeoDNS <a class="header-anchor" href="#geodns" aria-label="Permalink to &quot;GeoDNS&quot;">​</a></h1><div class="epigraph"><p>权威按解析器地址估用户位置，返回近的 A/AAAA；TTL 与缓存位置决定这份「地理」有多真。</p><footer>—— 据 RFC 7871 EDNS Client Subnet；CDN 实践；主干任播课对照整理</footer></div><p><a href="/cs/dns-cache-ttl">DNS TTL</a> 让答案被记住。<a href="/cs/anycast-edge">任播</a> 是路由侧近。<a href="/cs/doh-dot">上一课</a> 把递归器集中，位置更假。缺口是 <strong>GeoDNS</strong>：按源 IP 或 ECS 选答案。本课不把 SMTP 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全球用户打同一主机名，要近的边缘。<a href="/cs/cdn-intuition">CDN 直觉</a> 已点名。权威看递归器 IP 猜用户，误差大（公共解析器）。ECS 把客户端前缀带给权威，提高精度、泄露位置。任播：同一地址，路由选近；GeoDNS：不同地址。两者常叠。RPKI 管那些地址的源 AS。</p><p>不要把 GeoDNS 写成 GPS。</p><p><span class="marginnote">RFC 7871。隐私与缓存碎片是代价。本课不点名厂商。</span></p><h3 id="不是-gps" tabindex="-1">不是 GPS <a class="header-anchor" href="#不是-gps" aria-label="Permalink to &quot;不是 GPS&quot;">​</a></h3><p>按递归器或 ECS 估位置。任播是同址路由。TTL 约束切换。公共 DoH 使无 ECS 更钝。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：GeoDNS / 任播 / HTTP 302。画：查询源 → 地图 → 近记录。TTL 短才能切失败节点，与缓存课衔接。DoH 大解析器使无 ECS 时更钝。</p>',11)),(e(),l(c,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20SRC%5B%22%E9%80%92%E5%BD%92%E5%99%A8%E6%88%96%20ECS%22%5D%0A%20%20SRC%20--%3E%20MAP%5B%22%E5%9C%B0%E7%90%86%2F%E6%8B%93%E6%89%91%E5%9B%BE%22%5D%0A%20%20MAP%20--%3E%20ANS%5B%22%E8%BF%91%E7%9A%84%E5%9C%B0%E5%9D%80%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>负载均衡后课可再在地址集合上做。BGP 劫持会把「近」变成攻击者。测量 ping 后课验证是否真近。H3 HTTPS RR 也可按地返回不同目标。</p><p>缓存：同一递归器后的多国用户共享假位置，是公共 DNS 的经典坑。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IP 地理库的全部误差分析。SMTP/IMAP 是下一课。后课默认：GeoDNS 用查询源近似位置；ECS 更准更露。</p><p>把 TTL 设很长，故障切换要等过期。</p><p>上一课留下的缺口在本课收口；「GeoDNS」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/smtp-imap">SMTP / IMAP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>按解析器/ECS 选近地址。</li><li>与任播互补：一名多址 vs 同址路由。</li><li>公共解析器钝化地理。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 7871；CDN 实践。</li></ul>',10))])}const A=s(h,[["render",S]]);export{u as __pageData,A as default};
